import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { GearRatioComponent } from './gear-ratio.component';

const routes: Routes = [{ path: '', component: GearRatioComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class GearRatioRoutingModule { }
