import { Component, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { AlertController, IonContent, LoadingController, ToastController } from '@ionic/angular';
import { G } from 'src/app/core/common/G';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { async } from '@angular/core/testing';
import { GAccount } from '../../../../core/common/GAccount';
import { Urls } from '../../../../core/common/Urls';
import { GResponse } from '../../../../core/common/GResponse';
import { CourseService } from '../../../../data/service/course/course.service';
import { SliderService } from '../../../../data/service/site/Slider.service';
import { IGearRatioViewModel, IGearKeyValueViewModel } from '../../../../data/model/common/BaseModel';

@Component({
  selector: 'app-gear-ratio',
  templateUrl: './gear-ratio.component.html',
  styleUrls: ['./gear-ratio.component.scss']
})
export class GearRatioComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;

  queryText = '';
  isShow = false;
  isCheck = true;
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  form: FormGroup;
  GearRatioVideo: string | SafeUrl = 'g0lPh';

  gearRatio: IGearRatioViewModel = null;
  gearId = 1;
  carModelId = 1;
  carFactoryId = 1;
  isLoading = true;

  unitSelected = 'KmH';
  gearCountSelected = '5';
  gearCountSelectedNumber = 5;
  rimSizeSelected = '15';
  tireAspectRatioSelected = '65';
  tireSectionWidthSelected = '205';

  tireDiameter = 0;
  tireDiameterM = 0;
  pulsePerMile = 0;
  pulsePerKm = 0;
  teeth = 40;

  g1 = 0;
  g1rpm = 0;
  g2 = 0;
  g2rpm = 0;
  g3 = 0;
  g3rpm = 0;
  g4 = 0;
  g4rpm = 0;
  g5 = 0;
  g5rpm = 0;
  g6 = 0;
  g6rpm = 0;
  g7 = 0;
  g7rpm = 0;
  g8 = 0;
  gR = 0;
  resultRows: Array<{ gear: number; speed: number; shiftRpm: number | null }> = [];

  get topGearSpeed(): number {
    return this.resultRows.length ? this.resultRows[this.resultRows.length - 1].speed : 0;
  }

  get maxForwardSpeed(): number {
    return Math.max(1, ...this.resultRows.map(row => row.speed));
  }

  private updateResultRows(): void {
    const speeds = [this.g1, this.g2, this.g3, this.g4, this.g5, this.g6, this.g7, this.g8];
    const shiftRpms = [this.g1rpm, this.g2rpm, this.g3rpm, this.g4rpm,
      this.g5rpm, this.g6rpm, this.g7rpm];
    this.resultRows = speeds.slice(0, this.gearCountSelectedNumber).map((speed, index) => ({
      gear: index + 1,
      speed,
      shiftRpm: index < this.gearCountSelectedNumber - 1 ? shiftRpms[index] : null
    }));
  }

  constructor(
    private fb: FormBuilder,
    private router: Router,
    private sanitizer: DomSanitizer,
    public alertController: AlertController,
    public loadingController: LoadingController,
    private siteService: SliderService,
    public toastController: ToastController,
    private courseService: CourseService
  ) {
    this.isShow = false;
    if (!GAccount.IsLoggedIn()) {
      this.router.navigateByUrl('/Account');
    }
    this.check();
  }

  async check() {

    this.isLoading = true;

    SharedIonic.loading(this.loadingController);

    this.siteService.GetAllGearRatio().subscribe(
      res => {
        if (GResponse.SuccessStatus === res.status) {

          this.gearRatio = res.data;
          this.isLoading = false;
        } else {
          this.isLoading = false;
        }
      },
      err => {
        SharedIonic.unSuccessToast(this.toastController);
      }
    );

    this.siteService.GetTunerPlusById(20).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;

                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  getCityList(): IGearKeyValueViewModel[] {

    return this.gearRatio.carModelNames.filter(e => e.carFactoryNameId == this.carFactoryId);
  }

  getGearList(): IGearKeyValueViewModel[] {

    return this.gearRatio.gearBoxModelNames.filter(e => e.carModelNameId == this.carModelId);
  }

  changed3() {

    const model = this.gearRatio.gearBoxModelNames.find(e => e.id == this.gearId);

    if (model.g1 == '') {
      this.gearCountSelectedNumber = 3;
      this.gearCountSelected = '3';
    } else if (model.g2 == '') {
      this.gearCountSelectedNumber = 3;
      this.gearCountSelected = '3';
    } else if (model.g3 == '') {
      this.gearCountSelectedNumber = 3;
      this.gearCountSelected = '3';
    } else if (model.g4 == '') {
      this.gearCountSelectedNumber = 3;
      this.gearCountSelected = '3';
    } else if (model.g5 == '') {
      this.gearCountSelectedNumber = 4;
      this.gearCountSelected = '4';
    } else if (model.g6 == '') {
      this.gearCountSelectedNumber = 5;
      this.gearCountSelected = '5';
    } else if (model.g7 == '') {
      this.gearCountSelectedNumber = 6;
      this.gearCountSelected = '6';
    } else if (model.g8 == '') {
      this.gearCountSelectedNumber = 7;
      this.gearCountSelected = '7';
    } else if (model.g8 != '') {
      this.gearCountSelectedNumber = 8;
      this.gearCountSelected = '8';
    }

    this.form.setValue({
      g1: model.g1 == '' ? 1 : +model.g1,
      g2: model.g2 == '' ? 1 : +model.g2,
      g3: model.g3 == '' ? 1 : +model.g3,
      g4: model.g4 == '' ? 1 : +model.g4,
      g5: model.g5 == '' ? 1 : +model.g5,
      g6: model.g6 == '' ? 1 : +model.g6,
      g7: model.g7 == '' ? 1 : +model.g7,
      g8: model.g8 == '' ? 1 : +model.g8,
      gR: model.rev == '' ? 1 : +model.rev,
      axleRatio: model.def == '' ? 1 : +model.def,
      rpm: 6500
    });
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  checkURL() {
    const url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.GearRatioVideo +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    const url = 'https://www.aparat.com/v/' +
      this.GearRatioVideo;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  reset() {

    this.unitSelected = 'KmH';
    this.gearCountSelected = '5';
    this.gearCountSelectedNumber = 5;
    this.rimSizeSelected = '15';
    this.tireAspectRatioSelected = '65';
    this.tireSectionWidthSelected = '205';

    this.form.setValue({
      g1: 3.06,
      g2: 1.63,
      g3: 1.00,
      g4: 0.70,
      g5: 0.50,
      g6: 0.45,
      g7: 0.41,
      g8: 0.38,
      gR: 2.56,
      axleRatio: 3.07,
      rpm: 6500
    });
  }

  onInfo(type: string) {

    switch (type) {
      case 'Teeth':
        this.presentActiveAlertConfirm('برای بدست آوردن تعداد پالس به سنسور سرعت تعداد دندونه های شفت سنسور سرعت را وارد کنید');
        break;

      default:
        break;
    }
  }

  teethChanged() {

    this.onCalcTeeth();
  }

  async presentActiveAlertConfirm(msg: string = '') {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توضیحات',
      message: msg,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  unitChanged(nextUnit: string) {
    if ((nextUnit !== 'KmH' && nextUnit !== 'MPH') || nextUnit === this.unitSelected) {
      return;
    }

    this.unitSelected = nextUnit;
    this.cmptrfform();
  }

  gearCountChanged() {

    this.gearCountSelectedNumber = +this.gearCountSelected;

    switch (this.gearCountSelectedNumber) {
      case 3:
        this.form.setValue({
          g1: this.form.value.g1,
          g2: this.form.value.g2,
          g3: this.form.value.g3,
          g4: 0.70,
          g5: 0.50,
          g6: 0.45,
          g7: 0.41,
          g8: 0.38,
          gR: this.form.value.gR,
          axleRatio: this.form.value.axleRatio,
          rpm: this.form.value.rpm
        });
        break;
      case 4:
        this.form.setValue({
          g1: this.form.value.g1,
          g2: this.form.value.g2,
          g3: this.form.value.g3,
          g4: this.form.value.g4,
          g5: 0.50,
          g6: 0.45,
          g7: 0.41,
          g8: 0.38,
          gR: this.form.value.gR,
          axleRatio: this.form.value.axleRatio,
          rpm: this.form.value.rpm
        });
        break;
      case 5:
        this.form.setValue({
          g1: this.form.value.g1,
          g2: this.form.value.g2,
          g3: this.form.value.g3,
          g4: this.form.value.g4,
          g5: this.form.value.g5,
          g6: 0.45,
          g7: 0.41,
          g8: 0.38,
          gR: this.form.value.gR,
          axleRatio: this.form.value.axleRatio,
          rpm: this.form.value.rpm
        });
        break;
      case 6:
        this.form.setValue({
          g1: this.form.value.g1,
          g2: this.form.value.g2,
          g3: this.form.value.g3,
          g4: this.form.value.g4,
          g5: this.form.value.g5,
          g6: this.form.value.g6,
          g7: 0.41,
          g8: 0.38,
          gR: this.form.value.gR,
          axleRatio: this.form.value.axleRatio,
          rpm: this.form.value.rpm
        });
        break;
      case 7:
        this.form.setValue({
          g1: this.form.value.g1,
          g2: this.form.value.g2,
          g3: this.form.value.g3,
          g4: this.form.value.g4,
          g5: this.form.value.g5,
          g6: this.form.value.g6,
          g7: this.form.value.g7,
          g8: 0.38,
          gR: this.form.value.gR,
          axleRatio: this.form.value.axleRatio,
          rpm: this.form.value.rpm
        });
        break;
      case 8:
        this.form.setValue({
          g1: this.form.value.g1,
          g2: this.form.value.g2,
          g3: this.form.value.g3,
          g4: this.form.value.g4,
          g5: this.form.value.g5,
          g6: this.form.value.g6,
          g7: this.form.value.g7,
          g8: this.form.value.g8,
          gR: this.form.value.gR,
          axleRatio: this.form.value.axleRatio,
          rpm: this.form.value.rpm
        });
        break;

      default:
        this.form.reset();
        break;
    }
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
    this.GearRatioVideo = G.GearRatioVideo;

    this.form = this.fb.group({
      g1: [3.06, [Validators.required, Validators.min(0.01), Validators.max(1000)]],
      g2: [1.63, [Validators.required, Validators.min(0.01), Validators.max(1000)]],
      g3: [1.00, [Validators.required, Validators.min(0.01), Validators.max(1000)]],
      g4: [0.70, [Validators.required, Validators.min(0.01), Validators.max(1000)]],
      g5: [0.50, [Validators.required, Validators.min(0.01), Validators.max(1000)]],
      g6: [0.45, [Validators.required, Validators.min(0.01), Validators.max(1000)]],
      g7: [0.41, [Validators.required, Validators.min(0.01), Validators.max(1000)]],
      g8: [0.38, [Validators.required, Validators.min(0.01), Validators.max(1000)]],
      gR: [2.56, [Validators.required, Validators.min(0.01), Validators.max(1000)]],
      axleRatio: [3.07, [Validators.required, Validators.min(0.01), Validators.max(1000)]],
      rpm: [6500, [Validators.required, Validators.min(100), Validators.max(12000)]]
    });
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  onBack() {

    this.isShow = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  onCalc() {

    if (!this.form.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          this.cmptrfform();
          this.isShow = true;

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  async onCalcTeeth() {

    const tire_diameter =
      (1.0 * +this.tireSectionWidthSelected / 25.4) * (1.0 * +this.tireAspectRatioSelected / 50) + 1.0 * +this.rimSizeSelected;

    // tire_revs_mile = 5280/(3.1415926*form.tirediameter.value/12)
    const tire_revs_mile = 20168 / (tire_diameter); // use non-rounded value

    this.pulsePerMile = Math.round(tire_revs_mile * this.form.value.axleRatio * this.teeth);

    this.pulsePerKm = Math.round(this.pulsePerMile * 1.609344);
  }

  async cmptrfform() {

    const tire_diameter =
      (1.0 * +this.tireSectionWidthSelected / 25.4) * (1.0 * +this.tireAspectRatioSelected / 50) + 1.0 * +this.rimSizeSelected;

    this.tireDiameter = Math.round(10 * (tire_diameter)) / 10;
    this.tireDiameterM = +(this.tireDiameter * 0.0254).toFixed(3);

    // tire_revs_mile = 5280/(3.1415926*form.tirediameter.value/12)
    const tire_revs_mile = 20168 / (tire_diameter); // use non-rounded value

    this.pulsePerMile = Math.round(tire_revs_mile * this.form.value.axleRatio * this.teeth);

    this.pulsePerKm = Math.round(this.pulsePerMile * 1.609344);

    // tire revs/mile is 5280/(PI*tire_diam/12)
    // engine revs/mile is axle_ratio * gear_ratio * 5280/(PI*tire_diam/12)
    // revs per hour is rpm * 60
    // speed at redline is

    const revlimit = this.form.value.rpm * 60;

    this.g1 = Math.round((revlimit) / (this.form.value.axleRatio * this.form.value.g1 * tire_revs_mile));

    this.g1rpm = Math.round(this.form.value.g2 / this.form.value.g1 * this.form.value.rpm);

    this.g2 = Math.round((revlimit) / (this.form.value.axleRatio * this.form.value.g2 * tire_revs_mile));

    this.g2rpm = Math.round(this.form.value.g3 / this.form.value.g2 * this.form.value.rpm);

    this.g3 = Math.round((revlimit) / (this.form.value.axleRatio * this.form.value.g3 * tire_revs_mile));

    this.g3rpm = Math.round(this.form.value.g4 / this.form.value.g3 * this.form.value.rpm);

    this.g4 = Math.round((revlimit) / (this.form.value.axleRatio * this.form.value.g4 * tire_revs_mile));

    this.g4rpm = Math.round(this.form.value.g5 / this.form.value.g4 * this.form.value.rpm);

    this.g5 = Math.round((revlimit) / (this.form.value.axleRatio * this.form.value.g5 * tire_revs_mile));

    this.g5rpm = Math.round(this.form.value.g6 / this.form.value.g5 * this.form.value.rpm);

    this.g6 = Math.round((revlimit) / (this.form.value.axleRatio * this.form.value.g6 * tire_revs_mile));

    this.g6rpm = Math.round(this.form.value.g7 / this.form.value.g6 * this.form.value.rpm);

    this.g7 = Math.round((revlimit) / (this.form.value.axleRatio * this.form.value.g7 * tire_revs_mile));

    this.g7rpm = Math.round(this.form.value.g8 / this.form.value.g7 * this.form.value.rpm);

    this.g8 = Math.round((revlimit) / (this.form.value.axleRatio * this.form.value.g8 * tire_revs_mile));

    this.gR = Math.round(-1 * (revlimit) / (this.form.value.axleRatio * this.form.value.gR * tire_revs_mile));

    if (this.unitSelected === 'KmH') {

      this.g1 = Math.round(this.g1 * 1.609344);
      this.g2 = Math.round(this.g2 * 1.609344);
      this.g3 = Math.round(this.g3 * 1.609344);
      this.g4 = Math.round(this.g4 * 1.609344);
      this.g5 = Math.round(this.g5 * 1.609344);
      this.g6 = Math.round(this.g6 * 1.609344);
      this.g7 = Math.round(this.g7 * 1.609344);
      this.g8 = Math.round(this.g8 * 1.609344);
      this.gR = Math.round(this.gR * 1.609344);
    }
    this.updateResultRows();
  }
}
